import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.MembershipLevel;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Runs after {@link SaveOwner} on {@code POST /api/owners}, once the owner has been persisted and
 * assigned an id. Emits an audit line via the dedicated {@code AUDIT} logger carrying the new owner's
 * id, customerCode, registrationDate, membership level and membership number.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner) {
        AUDIT.info(
                "Created owner id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                MembershipLevel.of(owner), membershipNumber(owner));
    }

    private static String membershipNumber(Owner owner) {
        return owner.getCustomerCode() + "-M"
                + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
    }
}

